defmodule Angler.Media.CookiesTest do
  # load/0 reads the Angler.Media application environment, which some tests change.
  use ExUnit.Case, async: false

  import ExUnit.CaptureLog

  alias Angler.Media
  alias Angler.Media.Cookies
  alias Angler.Media.Cookies.Cookie

  @now 1_790_000_000
  @later 1_890_000_000

  # A file as yt-dlp and browser extensions write it, with CRLF line breaks.
  @file_contents Enum.join(
                   [
                     "# Netscape HTTP Cookie File",
                     "# This file is generated by yt-dlp.  Do not edit.",
                     "",
                     ".instagram.com\tTRUE\t/\tTRUE\t#{@later}\tsessionid\t25025320%3AabcDEF%3A12",
                     "#HttpOnly_.instagram.com\tTRUE\t/\tTRUE\t#{@later}.5\tds_user_id\t25025320",
                     "www.instagram.com\tFALSE\t/\tFALSE\t0\tcsrftoken\tTok3n",
                     ".tiktok.com\tTRUE\t/\tTRUE\t\tsessionid_ss\tabc",
                     ""
                   ],
                   "\r\n"
                 )

  defp cookie(attrs) do
    struct!(%Cookie{domain: "instagram.com", name: "a", value: "1"}, attrs)
  end

  describe "parse/1" do
    test "reads cookies, #HttpOnly_ lines and session cookies, and skips comments" do
      assert [session, user, csrf, tiktok] = Cookies.parse(@file_contents)

      assert session == %Cookie{
               domain: "instagram.com",
               include_subdomains: true,
               path: "/",
               secure: true,
               expires: @later,
               name: "sessionid",
               value: "25025320%3AabcDEF%3A12"
             }

      assert %Cookie{name: "ds_user_id", value: "25025320", expires: @later} = user

      assert %Cookie{domain: "www.instagram.com", include_subdomains: false, secure: false} =
               csrf

      assert csrf.expires == nil
      assert %Cookie{domain: "tiktok.com", name: "sessionid_ss", expires: nil} = tiktok
    end

    test "strips a byte order mark and keeps empty values" do
      contents =
        "﻿example.com\tFALSE\t/\tFALSE\t0\tempty\t\nexample.com\tFALSE\t/\tFALSE\t0\tb\t2"

      assert [%Cookie{name: "empty", value: ""}, %Cookie{name: "b", value: "2"}] =
               Cookies.parse(contents)
    end

    test "treats a leading dot or TRUE as including subdomains, and lowercases the domain" do
      assert [
               %Cookie{domain: "example.com", include_subdomains: true},
               %Cookie{domain: "example.com", include_subdomains: true},
               %Cookie{domain: "example.com", include_subdomains: false, path: "/"}
             ] =
               Cookies.parse("""
               .Example.COM\tFALSE\t/\tFALSE\t0\ta\t1
               example.com\tTRUE\t/\tFALSE\t0\tb\t2
               example.com\tFALSE\t\tFALSE\t0\tc\t3
               """)
    end

    test "lets a later line replace an earlier cookie with the same domain, path and name" do
      cookies =
        Cookies.parse("""
        .tiktok.com	TRUE	/	TRUE	0	sessionid	OLD
        .tiktok.com	TRUE	/	TRUE	0	tt_csrf	c
        www.tiktok.com	FALSE	/	TRUE	0	sessionid	WWW
        .tiktok.com	TRUE	/api	TRUE	0	sessionid	API
        tiktok.com	TRUE	/	TRUE	0	sessionid	NEW
        """)

      # In the place of the first one.
      assert [
               %Cookie{domain: "tiktok.com", path: "/", name: "sessionid", value: "NEW"},
               %Cookie{name: "tt_csrf"},
               %Cookie{domain: "www.tiktok.com", value: "WWW"},
               %Cookie{path: "/api", value: "API"}
             ] = cookies

      assert Cookies.header(cookies, "https://tiktok.com/@a/photo/1", @now) ==
               "sessionid=NEW; tt_csrf=c"

      # Across domains and paths, the most specific still wins.
      assert Cookies.header(cookies, "https://www.tiktok.com/@a/photo/1", @now) ==
               "sessionid=WWW; tt_csrf=c"

      assert Cookies.header(cookies, "https://tiktok.com/api/item", @now) ==
               "sessionid=API; tt_csrf=c"
    end

    test "skips lines that aren't valid cookies" do
      for line <- [
            "example.com\tFALSE\t/\tFALSE\t0\tname",
            "example.com\tFALSE\t/\tFALSE\t0\ta\t1\textra",
            "example.com\tFALSE\t/\tFALSE\tsoon\ta\t1",
            "example.com\tFALSE\t/\tFALSE\t0\tna me\t1",
            "example.com\tFALSE\t/\tFALSE\t0\ta;b\t1",
            "example.com\tFALSE\t/\tFALSE\t0\ta\tcafé",
            "example.com\tFALSE\t/\tFALSE\t0\ta\tb;c",
            "example.com\tFALSE\t/\tFALSE\t0\ta\tb c",
            "example.com\tFALSE\t/\tFALSE\t0\ta\t\"unbalanced",
            "example.com\tFALSE\t/\tFALSE\t0\ta\tback\\slash",
            "\tFALSE\t/\tFALSE\t0\ta\t1",
            "exa mple.com\tFALSE\t/\tFALSE\t0\ta\t1",
            "just some text"
          ] do
        assert Cookies.parse(line) == [], inspect(line)
      end

      assert [%Cookie{value: ~s("quoted")}] =
               Cookies.parse(~s(example.com\tFALSE\t/\tFALSE\t0\ta\t"quoted"))
    end
  end

  describe "header/3" do
    test "sends matching cookies, the most specific domain and longest path first" do
      cookies = [
        cookie(domain: "instagram.com", include_subdomains: true, name: "mid", value: "m"),
        cookie(domain: "instagram.com", include_subdomains: true, name: "sessionid", value: "s1"),
        cookie(domain: "www.instagram.com", name: "sessionid", value: "s2"),
        cookie(domain: "www.instagram.com", path: "/p", name: "p", value: "1")
      ]

      assert Cookies.header(cookies, "https://www.instagram.com/p/abc/", @now) ==
               "p=1; sessionid=s2; mid=m"

      assert Cookies.header(cookies, "https://instagram.com/", @now) == "mid=m; sessionid=s1"
    end

    test "matches domains exactly unless subdomains are included, and never for IP addresses" do
      host_only = [cookie(domain: "example.com")]
      assert Cookies.header(host_only, "https://example.com/", @now) == "a=1"
      assert Cookies.header(host_only, "https://www.example.com/", @now) == nil

      subdomains = [cookie(domain: "example.com", include_subdomains: true)]
      assert Cookies.header(subdomains, "https://a.b.EXAMPLE.com/", @now) == "a=1"
      assert Cookies.header(subdomains, "https://notexample.com/", @now) == nil
      assert Cookies.header(subdomains, "https://example.com.evil.test/", @now) == nil

      ip = [cookie(domain: "0.0.1", include_subdomains: true)]
      assert Cookies.header(ip, "https://127.0.0.1/", @now) == nil
    end

    test "matches paths on segment boundaries" do
      cookies = [cookie(path: "/p")]

      for path <- ["/p", "/p/", "/p/abc"],
          do: assert(Cookies.header(cookies, "https://instagram.com" <> path, @now) == "a=1")

      for path <- ["/", "/photos", ""],
          do: assert(Cookies.header(cookies, "https://instagram.com" <> path, @now) == nil)

      assert Cookies.header([cookie(path: "/p/")], "https://instagram.com/p/x", @now) == "a=1"
    end

    test "sends secure cookies over HTTPS only, and no expired cookies" do
      cookies = [
        cookie(name: "secure", secure: true),
        cookie(name: "expired", expires: @now - 1),
        cookie(name: "session", expires: nil),
        cookie(name: "valid", expires: @now + 1)
      ]

      assert Cookies.header(cookies, "https://instagram.com/", @now) ==
               "secure=1; session=1; valid=1"

      assert Cookies.header(cookies, "http://instagram.com/", @now) == "session=1; valid=1"
      assert Cookies.header(cookies, "ftp://instagram.com/", @now) == nil
      assert Cookies.header(cookies, "not a url", @now) == nil
      assert Cookies.header([], "https://instagram.com/", @now) == nil
    end
  end

  test "merge/2 joins cookie headers, the later value of a name winning" do
    assert Cookies.merge("a=1; b=2", "b=3; c=4") == "a=1; b=3; c=4"
    assert Cookies.merge(nil, "c=4") == "c=4"
    assert Cookies.merge("a=1;", nil) == "a=1"
    assert Cookies.merge(nil, nil) == nil
  end

  test "inspect/2 leaves the value out" do
    inspected = inspect(cookie(name: "sessionid", value: "SECRET123"))
    assert inspected =~ "sessionid"
    refute inspected =~ "SECRET123"
  end

  test "request_error/1 never includes the exception message" do
    assert Cookies.request_error(%Req.TransportError{reason: :timeout}) ==
             "network error (timeout)"

    error = %Req.HTTPError{
      protocol: :http1,
      reason: {:invalid_header_value, "cookie", "s=SECRET"}
    }

    assert Cookies.request_error(error) == "network error (Req.HTTPError)"

    assert Cookies.request_error(%RuntimeError{message: "s=SECRET"}) ==
             "network error (RuntimeError)"
  end

  describe "load/0 and configured?/0" do
    @describetag :tmp_dir

    setup do
      original = Application.get_env(:angler, Media)
      on_exit(fn -> Application.put_env(:angler, Media, original) end)
      :ok
    end

    defp configure(path) do
      Application.put_env(
        :angler,
        Media,
        Keyword.put(Application.get_env(:angler, Media), :cookies_file, path)
      )
    end

    test "read the configured file on every call", %{tmp_dir: tmp_dir} do
      configure(nil)
      refute Cookies.configured?()
      assert Cookies.load() == []

      path = Path.join(tmp_dir, "cookies.txt")
      File.write!(path, @file_contents)
      configure(path)

      assert Cookies.configured?()
      assert [%Cookie{name: "sessionid"} | _rest] = Cookies.load()

      File.write!(path, "example.com\tFALSE\t/\tFALSE\t0\tother\t1\n")
      assert [%Cookie{name: "other"}] = Cookies.load()
    end

    test "log skipped lines by number, never their contents", %{tmp_dir: tmp_dir} do
      path = Path.join(tmp_dir, "cookies.txt")

      File.write!(
        path,
        "example.com\tFALSE\t/\tFALSE\t0\tgood\t1\nexample.com\tFALSE\t/\tFALSE\t0\tbad\tSECRET café\n"
      )

      configure(path)

      log = capture_log(fn -> assert [%Cookie{name: "good"}] = Cookies.load() end)
      assert log =~ "Ignoring 1 lines of the cookies file that are not valid cookies (lines 2)"
      refute log =~ "SECRET"
    end

    test "ignore unreadable and oversized files", %{tmp_dir: tmp_dir} do
      configure(Path.join(tmp_dir, "missing.txt"))
      assert Cookies.configured?()

      assert capture_log(fn -> assert Cookies.load() == [] end) =~
               "Ignoring the cookies file: no such file or directory"

      big = Path.join(tmp_dir, "big.txt")
      line = "example.com\tFALSE\t/\tFALSE\t0\tname\tSECRET\n"
      File.write!(big, String.duplicate(line, div(1_000_000, byte_size(line)) + 1))
      configure(big)

      log = capture_log(fn -> assert Cookies.load() == [] end)
      assert log =~ "Ignoring the cookies file: it is larger than 1 MB"
      refute log =~ "SECRET"
    end
  end
end
